// Issue #27 replacement coverage: the public equivalents of the corpus-only
// checks (docs/legal/ISSUE_27_HISTORY_REMEDIATION_PLAN.md §4), on ORIGINAL CC0
// fixtures generated by tools/make_synthetic_sty.py. Runs with no corpus:
//   WALTZ_68    6/8 meter (time_signature, style_load_safety)
//   FULL_SFF2   all 15 sections, non-default tempo, guitar NTR 2, Korg export,
//               UASF golden (sff1_tempo, uasf_tempo, uasf_golden, mapper_casm_ntr,
//               korg_corpus_conversion, section lifecycle / fill return)
//   BREAK_TAIL  unmarked tail after Fill In BA (#26): raw data preserved, Break
//               still not exported

#include "importers/sff1/sff1_reader.h"
#include "importers/sff1/sff1_mapper.h"
#include "exporters/korg/genos_to_korg.h"
#include "exporters/korg/korg_style_smf.h"
#include "exporters/korg/sff1_route.h"
#include "engine/arranger/style_player.h"
#include "engine/arranger/chord_input.h"
#include "engine/realtime/clock.h"
#include "engine/midi/scheduler.h"
#include "engine/midi/panic.h"
#include "engine/uasf/serializer.h"
#include "engine/uasf/deserializer.h"
#include <algorithm>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <set>
#include <string>
#include <vector>

using namespace ai_arranger;
using namespace ai_arranger::importers::sff1;
namespace korg = ai_arranger::exporters::korg;

static int failures = 0, passes = 0;
#define TEST(name, expr) do { \
    if (!(expr)) { std::fprintf(stderr, "  FAIL: %s\n", name); ++failures; } \
    else { std::printf("  PASS: %s\n", name); ++passes; } } while (0)

static std::string fx(const char* name) { return std::string(REPO_DIR) + "/fixtures/synthetic/" + name; }

static int indexOf(const uasf::StyleDefinition& s, uasf::SectionType t) {
    for (size_t i = 0; i < s.sections.size(); ++i)
        if (s.sections[i].type == t) return static_cast<int>(i);
    return -1;
}

static long noteOns(const uasf::StyleDefinition& s) {
    long n = 0;
    for (const auto& sec : s.sections)
        for (const auto& t : sec.tracks)
            for (const auto& e : t.events) n += e.type == uasf::MidiEventType::NoteOn && e.data2 > 0;
    return n;
}

// Count NoteOn (velocity > 0) in the raw SMF, independent of the importer.
static long rawNoteOns(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    const std::vector<uint8_t> b((std::istreambuf_iterator<char>(in)), {});
    size_t p = 14;                                     // after MThd
    if (b.size() < 22 || std::string(b.begin() + p, b.begin() + p + 4) != "MTrk") return -1;
    const size_t end = p + 8 + ((b[p + 4] << 24) | (b[p + 5] << 16) | (b[p + 6] << 8) | b[p + 7]);
    p += 8;
    long n = 0;
    while (p < end) {
        while (b[p] & 0x80) ++p;                       // delta VLQ
        ++p;
        const uint8_t st = b[p++];
        if (st == 0xFF) { p += 1; uint32_t len = 0; do { len = (len << 7) | (b[p] & 0x7F); } while (b[p++] & 0x80); p += len; }
        else if ((st & 0xF0) == 0xC0) p += 1;
        else { n += (st & 0xF0) == 0x90 && b[p + 1] > 0; p += 2; }   // generator writes no running status
    }
    return n;
}

struct Rig {
    realtime::RealtimeClock clk; midi::MidiScheduler sch; midi::PanicHandler pan;
    arranger::StylePlayer p{clk, sch, pan};
    int balance = 0;
    Rig() {
        sch.setOutputCallback([this](const uasf::MidiEvent& e) {
            if (e.type == uasf::MidiEventType::NoteOn && e.data2 > 0) ++balance;
            else if (e.type == uasf::MidiEventType::NoteOff ||
                     (e.type == uasf::MidiEventType::NoteOn && e.data2 == 0)) --balance;
        });
        clk.setSampleRate(48000);
    }
    void runTo(int64_t tick) {
        for (int guard = 0; clk.getPosition() < tick && guard < 1'000'000; ++guard) {
            clk.advance(48); p.tick(); sch.advanceTo(clk.getPosition());
        }
    }
};

int main() {
    std::printf("Test: synthetic replacement corpus (#27)\n");

    // ── 6/8 ──
    {
        const auto pr = Sff1Reader().parseFile(fx("SYNTH_WALTZ_68.sty"));
        TEST("waltz: SMF time signature 6/8", pr.success && pr.time_sig_num == 6 && pr.time_sig_den == 8);
        const auto mr = Sff1ToUasfMapper().map(pr);
        bool ts = mr.success && !mr.style.sections.empty(), fill1 = false, main4 = false;
        for (const auto& s : mr.style.sections) {
            ts &= s.beats_per_bar == 6 && s.beat_note == 8;
            if (s.type == uasf::SectionType::Fill1) fill1 = s.bars == 1;
            if (s.type == uasf::SectionType::Main1) main4 = s.bars == 4;
        }
        TEST("waltz: every section carries 6/8", ts);
        TEST("waltz: Fill In AA 1 bar, Main A 4 bars of 6/8", fill1 && main4);
        TEST("waltz: tempo 132 BPM", mr.style.tempo_bpm == 132);

        Rig r;
        r.clk.setTempo(mr.style.tempo_bpm);
        r.p.loadStyle(mr.style);
        TEST("waltz: load while stopped adopts 5760-tick bars", r.clk.ticksPerBar() == 5760);
        const int mainA = indexOf(mr.style, uasf::SectionType::Main1);
        const int fillAA = indexOf(mr.style, uasf::SectionType::Fill1);
        r.p.start(mainA);
        r.runTo(5760 + 10);
        r.p.fill();
        r.runTo(2 * 5760 + 10);
        TEST("waltz: fill starts on the 6/8 bar line", r.p.getCurrentSection() == fillAA);
        r.runTo(3 * 5760 + 10);
        TEST("waltz: fill returns to Main A after one 6/8 bar", r.p.getCurrentSection() == mainA);
        r.p.stop();
        r.sch.advanceTo(r.clk.getPosition());
        TEST("waltz: no stuck notes", r.balance == 0);
    }

    // ── All 15 sections, tempo, guitar NTR, export, golden ──
    {
        const auto pr = Sff1Reader().parseFile(fx("SYNTH_FULL_SFF2.sty"));
        const auto mr = Sff1ToUasfMapper().map(pr);
        TEST("full: imports", pr.success && mr.success);
        std::set<int> types;
        for (const auto& s : mr.style.sections) types.insert(static_cast<int>(s.type));
        TEST("full: all 15 section types, each once", types.size() == 15 && mr.style.sections.size() == 15);
        TEST("full: tempo 92 BPM (652174 us/q)", mr.style.tempo_bpm == 92);

        bool guitar = false, guitarOk = true;
        for (const auto& cs : mr.casm_sections)
            for (const auto& t : cs.tracks)
                if (t.name == "Chord2") { guitar = true; guitarOk &= t.articulation.ntr == 2 && t.articulation.ntt == 1; }
        TEST("full: guitar track keeps NTR 2 / NTT 1 in every CASM section", guitar && guitarOk);

        korg::MapOptions opt;
        opt.route = korg::routeFromCasm(pr);
        const auto kr = korg::mapToKorg(mr.style, opt);
        std::set<std::string> markers;
        for (const auto& e : kr.style.elements) markers.insert(e.marker);
        TEST("full: Korg export 14 elements, validator PASS",
             kr.ok && kr.style.elements.size() == 14 && korg::validate(kr.style).empty());
        TEST("full: Intro 1-3, Variation 1-4, Fill 1-4, Ending 1-3 markers",
             markers.count("i3cv1") && markers.count("v4cv1") && markers.count("f4cv1") && markers.count("e3cv1"));
        TEST("full: Break withheld (#26)",
             std::any_of(kr.report.sections.begin(), kr.report.sections.end(),
                         [](const korg::SectionRow& s) { return s.source == "Fill In BA" && s.marker.empty(); }));

        const auto ser = uasf::UasfSerializer().serialize(mr.style);
        const auto back = uasf::UasfDeserializer().deserialize(ser.data);
        TEST("full: UASF round trip keeps tempo and every note",
             ser.success && back.success && back.style.tempo_bpm == 92 && noteOns(back.style) == noteOns(mr.style));
        std::ifstream g(fx("SYNTH_FULL_SFF2.uasf"), std::ios::binary);
        const std::vector<uint8_t> golden((std::istreambuf_iterator<char>(g)), {});
        TEST("full: matches the committed UASF golden byte for byte", !golden.empty() && ser.data == golden);

        // Every Main with a chord change mid-way and its fill: no stuck notes.
        Rig r;
        r.clk.setTempo(mr.style.tempo_bpm);
        r.p.loadStyle(mr.style);
        const int64_t bar = r.clk.ticksPerBar();
        bool returns = true;
        int64_t at = 0;
        r.p.start(indexOf(mr.style, uasf::SectionType::Main1));
        const uasf::SectionType mains[] = {uasf::SectionType::Main1, uasf::SectionType::Main2,
                                           uasf::SectionType::Main3, uasf::SectionType::Main4};
        for (int m = 0; m < 4; ++m) {
            const int idx = indexOf(mr.style, mains[m]);
            r.p.switchSection(idx);
            at = (at / bar + 1) * bar;
            r.runTo(at + 10);
            r.p.setChord({arranger::ChordType::Minor, static_cast<uint8_t>(57 + m), 0, 0});
            r.runTo(at + bar / 2);
            r.p.fill();
            r.runTo(at + 2 * bar + 10);   // fill bar, then back
            returns &= r.p.getCurrentSection() == idx;
            at += 2 * bar;
        }
        TEST("full: each Main's fill returns to that Main", returns);
        r.p.stop();
        r.sch.advanceTo(r.clk.getPosition());
        TEST("full: no stuck notes across Mains, fills and chord changes", r.balance == 0);
    }

    // ── Unmarked tail after Fill In BA (#26): preserved, not exported ──
    {
        const std::string path = fx("SYNTH_BREAK_TAIL.sty");
        const auto pr = Sff1Reader().parseFile(path);
        const auto mr = Sff1ToUasfMapper().map(pr);
        TEST("tail: imports", pr.success && mr.success);
        TEST("tail: every NoteOn in the file survives import (raw data preserved)",
             rawNoteOns(path) > 0 && noteOns(mr.style) == rawNoteOns(path));
        korg::MapOptions opt;
        opt.route = korg::routeFromCasm(pr);
        const auto kr = korg::mapToKorg(mr.style, opt);
        TEST("tail: Break still not exported, Main A is",
             kr.ok && kr.style.elements.size() == 1 && kr.style.elements[0].marker == "v1cv1");
    }

    std::printf("\n%d passed, %d failed\n", passes, failures);
    return failures ? 1 : 0;
}
